import{_ as a,o as i,c as l,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Days Asia- NVMe-oF recovery- Robust Ceph design through disaggregating domains","description":"","frontmatter":{"title":"Ceph Days Asia- NVMe-oF recovery- Robust Ceph design through disaggregating domains","date":"2024-10-03T00:00:00.000Z","updated":"2024-10-03T00:00:00.000Z","tags":["Ceph","Distributed Storage","High Availability","NVMe","oF Recovery","System Design"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Ceph_Days_Asia_-_NVMe-oF_recovery_-_Robust_Ceph_design_through_disaggregating_domains.md","filePath":"posts/2024/Ceph_Days_Asia_-_NVMe-oF_recovery_-_Robust_Ceph_design_through_disaggregating_domains.md","lastUpdated":1780459816000}'),t={name:"posts/2024/Ceph_Days_Asia_-_NVMe-oF_recovery_-_Robust_Ceph_design_through_disaggregating_domains.md"};function o(s,e,h,n,_,g){return i(),l("div",null,[...e[0]||(e[0]=[r('<p>会议纪要</p><h3 id="会议主题-使用mbm-fabric实现ceph的高可用性和快速恢复设计" tabindex="-1">会议主题：使用MBM Fabric实现Ceph的高可用性和快速恢复设计 <a class="header-anchor" href="#会议主题-使用mbm-fabric实现ceph的高可用性和快速恢复设计" aria-label="Permalink to &quot;会议主题：使用MBM Fabric实现Ceph的高可用性和快速恢复设计&quot;">​</a></h3><h3 id="主讲人-kang-cheol-三星电子" tabindex="-1">主讲人：Kang Cheol (三星电子) <a class="header-anchor" href="#主讲人-kang-cheol-三星电子" aria-label="Permalink to &quot;主讲人：Kang Cheol (三星电子)&quot;">​</a></h3><h3 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h3><ol><li><p><strong>背景介绍</strong>：</p><ul><li>集群环境中计算节点故障频繁，故障率随服务器使用时间增长而增加。</li><li>Meta的数据显示，在预训练过程中，服务器硬件故障导致频繁故障。</li><li>现有分布式存储系统如Ceph依赖复制和重新平衡技术，但存在性能下降的问题。</li></ul></li><li><p><strong>现有技术及挑战</strong>：</p><ul><li>Ceph通过副本机制保证数据一致性和系统可用性，但新OSD的添加会导致数据重新平衡，可能降低性能。</li><li>当OSD故障时，Ceph通过其他副本保证数据可用，并快速创建新的副本集。</li></ul></li><li><p><strong>MBM Fabric的引入</strong>：</p><ul><li>MBM Fabric通过网络将计算域和存储域分离，提高性能并减少物理限制。</li><li>将MBM Fabric直接应用于Ceph存在挑战，因为Ceph设计基于DAS环境。</li></ul></li><li><p><strong>设计改进与快速恢复策略</strong>：</p><ul><li>引入新的控制器和虚拟主机概念，自动化设备连接和计算节点间的移动。</li><li>通过虚拟主机概念管理fabric域，减少不必要的恢复过程。</li><li>在Ceph的Lu Operator中添加新控制器，实现快速恢复。</li></ul></li><li><p><strong>具体实施步骤</strong>：</p><ul><li>注册fabric设备信息，通过控制器处理事件，连接设备到计算节点。</li><li>运行OSD并引入虚拟主机概念，确保在故障域内自由移动设备，避免不必要的恢复过程。</li></ul></li><li><p><strong>预期效果</strong>：</p><ul><li>通过新的设计，消除不必要的IO，提高系统性能。</li><li>预计结合Ceph和相关产品，创建新的存储解决方案。</li></ul></li></ol><h3 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h3><ul><li>确认了MBM Fabric在Ceph中的应用价值和必要性。</li><li>确定了通过引入新控制器和虚拟主机概念来实现快速恢复的策略。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h3><ul><li>继续开发和测试MBM Fabric在Ceph中的实现。</li><li>探索与三星等公司产品的集成可能性，以创建更强大的存储解决方案。</li></ul><h3 id="结束语" tabindex="-1">结束语： <a class="header-anchor" href="#结束语" aria-label="Permalink to &quot;结束语：&quot;">​</a></h3><ul><li>Kang Cheol感谢大家的参与，并期待通过Fast Recovery为Ceph带来更坚实的基础。</li></ul>',11)])])}const u=a(t,[["render",o]]);export{d as __pageData,u as default};
